// p2_tsp_setup: the TSP's plane setup and mip K as a microprogrammed unit (PLAN M9; ARCHITECTURE 3.7.3; tsp 2.3, 4.1-4.6,
// 8.1 at refsw3 4f3efe15: pvr_tsp_plane.h PlaneT::Setup, refsw_tile.h IPs3::Setup / SetupIntensity, MipSelect's K part).
// It takes one fetched primitive a job (p2_tsp_pfetch), chooses its setup class, loads the ALU's input registers, writes
// the entry's header into p2_tsp_store, runs the class's program (rtl/v1/pkg/p2_tsp_prog_pkg.sv, GENERATED by
// tools/gen/gen_tsp_prog.cpp from the operation graphs) on p2_tsp_alu and makes the program's store writes.
//
// The accept (pr_v && pr_rdy) is the job's start:
//   the corners                X, Y, Z = FromSingle(., 1) of the fetched x, y, z (num H4)
//   the attributes at corners  U, V as fetched; the colours c x 2^-8 (SingleBits(c, -8): p2_fp_in_colour) of B, G, R, A
//                              and of the offset colour; flat shading (ISP Gouraud 0) v3's at all three corners
//                              (IPs3::Setup L157-163); the intensity entry (vsel and FPU_SHAD_SCALE[8]) the colours
//                              (c * scale) >> 8 per vertex for B, G, R, not A (SetupIntensity) [modvol: 0x80 halves,
//                              0xFF one level; sc_ingame2]
//   the class                  untextured (the 1/w plane and the colours); textured: also U, V; the offset planes when
//                              Texture && Offset && the volume's texture is not a bump map (the only case PixelFlush_tsp
//                              interpolates them), DROPPED when every offset colour the entry uses is 0 (Gouraud: the
//                              three corners, flat: v3, the intensity entry: the scaled ones) [M tim 3.7 vol2off, offs3:
//                              "+16 a triangle disappears"; whether the console looks at the scaled or the sent colours
//                              is GAP]; K when the volume's TCW is mipmapped, with DCalcCtrl 1 the sums at the first vertex
//   the header                 the ISP word, TSP and TCW of the volume tv = vsel && !intensity, the fallbacks (v3's colour
//                              and offset colour as sent, scaled for the intensity entry: IPs3 fallback), the class
// Step 0 of the program is the clock after the accept. A step issues when run start does not hold the ALU (`hold`,
// ARCHITECTURE 3.7.4 "run start first" [G]: the whole step waits, the units' pipelines run on). The store writes
// (the micro-word's w slot, one a step: the store's write port):
//   W_PL  a plane: flat (the determinant Sdet zero, or perpendicular to FPU_PERP_VAL: PlaneT::Setup L257-259) A = B = +0,
//         C = cut16(the flat C: the mean, an attribute times it); else cut16(A0), cut16(B0), cut16(C0)
//   W_DR  a dropped offset plane, no multiply (ARCHITECTURE 3.7.3's table at 4f3efe15: the attribute's terms are zeros
//         and every sum that is zero is +0, so A0 = +0 x inv): flat A = B = +0, C = a zero of the mean's sign; else
//         A, B, C zeros of Sdet's sign (inv's: Recip and the zero reciprocals keep the determinant's sign)
//   W_K   K (MipSelect L833-847): with Sdet zero the length of all ones 0xFFFFFF 2^-23 (dzForce); an infinite length
//         2^(-128 + size), a zero one 2^(-127 + size), else cut8(best x bias x 2^(size - 2)); bias the TSP's MipMapD,
//         0 read as 4 (refsw_tile.cpp mipChoose L1950-1951: Berserk, mipmeas --bias0), size 3 + TexU
// The program's last step is its last store write: `done` then (the entry ready), and the next job is accepted in that
// clock.
module p2_tsp_setup
  import p2_hw_pkg::*;
  import p2_pkg::*;
  import p2_fp_pkg::*;
  import p2_tsp_pkg::*;
  import p2_tsp_prog_pkg::*;
(
  input  logic                         clk,
  input  logic                         rst,
  // the fetched primitive (p2_tsp_pfetch), valid/ready
  input  logic                         pr_v,
  output logic                         pr_rdy,
  input  p2_tsp_prim_t                 pr,
  // the render's registers
  input  logic [31:0]                  fpu_shad_scale,   // FPU_SHAD_SCALE
  input  logic [31:0]                  fpu_perp_val,     // FPU_PERP_VAL
  // run start has the ALU this clock: no step issues
  input  logic                         hold,
  // the store's write ports
  output logic                         sh_v,             // the header, at the accept
  output logic [P2_TSP_SIDX_BITS-1:0]  sh_idx,
  output p2_tsp_hdr_t                  sh_w,
  output logic                         sp_v,             // a plane
  output logic [P2_TSP_SIDX_BITS-1:0]  sp_idx,
  output logic [3:0]                   sp_plane,
  output p2_tsp_plane_t                sp_w,
  output logic                         sk_v,             // K
  output logic [P2_TSP_SIDX_BITS-1:0]  sk_idx,
  output p2_tsp_k_t                    sk_w,
  output logic                         done,             // the job's last store write: its entry is ready
  output logic [P2_TSP_SIDX_BITS-1:0]  done_idx,
  output logic                         idle,
  // taps (the testbench's program trace; not a hardware interface)
  output logic                         t_issue,
  output logic [3:0]                   t_cls,
  output logic [P2_TSP_PC_BITS-1:0]    t_pc,
  output p2_tsp_uword_t                t_uw,
  output logic [P2_TSP_NM+P2_TSP_NA:0]                  t_wv,
  output logic [P2_TSP_NM+P2_TSP_NA:0][P2_TSP_RW-1:0]   t_wrd
);
  // ---------------------------------------------------------------------------------------------- the program
  logic                        act;
  logic [3:0]                  cls;
  logic [P2_TSP_PC_BITS-1:0]   pc, len;
  logic [P2_TSP_SIDX_BITS-1:0] sidx;
  logic [3:0]                  j_mipd;           // the job's TSP MipMapD (D adjust) and TexU
  logic [2:0]                  j_texu;
  logic                        step, last, take;
  p2_tsp_uword_t               uw;

  assign uw     = p2_tsp_prog(cls, pc);
  assign step   = act && !hold;
  assign last   = step && pc == len - P2_TSP_PC_BITS'(1);
  assign pr_rdy = !act || last;
  assign take   = pr_v && pr_rdy;
  assign idle   = !act;

  // ---------------------------------------------------------------------------------------------- the accept
  logic        intensity, gour;
  logic [7:0]  scale;
  p2_tsp_hdr_t hdr;
  logic [3:0]  cls_in;
  // the colour channels at each corner as the planes take them: flat v3's, intensity-scaled
  logic [2:0][3:0][7:0] cc, oc;
  assign intensity = pr.job.vsel && fpu_shad_scale[8];
  assign scale     = fpu_shad_scale[7:0];
  assign gour      = pr.isp[23];
  always_comb begin
    for (int k = 0; k < 3; k++)
      for (int ch = 0; ch < 4; ch++) begin
        logic [7:0]  c0, o0;
        logic [15:0] cs, os;
        c0 = pr.col[gour ? k : 2][8*ch +: 8];
        o0 = pr.spc[gour ? k : 2][8*ch +: 8];
        cs = {8'h00, c0} * {8'h00, scale};
        os = {8'h00, o0} * {8'h00, scale};
        cc[k][ch] = (intensity && ch < 3) ? cs[15:8] : c0;
        oc[k][ch] = (intensity && ch < 3) ? os[15:8] : o0;
      end
  end
  // the class (gen_tsp_prog.cpp kCls: UNTEX, TEX, TEX_M0, TEX_M1, TEX_O, TEX_O_M0, TEX_O_M1, TEX_D, TEX_D_M0, TEX_D_M1)
  always_comb begin
    logic       tex, ofs, zero, mip;
    logic [1:0] o, m;
    tex  = pr.isp[25];
    ofs  = pr.isp[24] && pr.tcw[29:27] != 3'd4;
    zero = 1'b1;
    for (int k = 0; k < 3; k++)
      for (int ch = 0; ch < 4; ch++)
        if (oc[k][ch] != 8'h00) zero = 1'b0;
    mip  = pr.tcw[31];
    o    = !ofs ? 2'd0 : zero ? 2'd2 : 2'd1;
    m    = !mip ? 2'd0 : pr.isp[20] ? 2'd2 : 2'd1;
    if (!tex) cls_in = P2_TSP_CLS_UNTEX;
    else cls_in = 4'd1 + 4'(o) * 4'd3 + 4'(m);
  end
  always_comb begin
    hdr           = '0;
    hdr.isp       = pr.isp;
    hdr.tsp       = pr.tsp;
    hdr.tcw       = pr.tcw;
    hdr.col_fb    = cc[2];
    hdr.ofs_fb    = oc[2];
    hdr.vsel      = pr.job.vsel;
    hdr.intensity = intensity;
    hdr.cls       = cls_in;
  end

  // the input registers
  p2_fp24_t [P2_TSP_NIN-1:0] ld_val;
  p2_fp24_t [2:0]            xf, yf, zf, uf, vf;
  p2_fp24_t [2:0][3:0]       cf, of;
  genvar g, h;
  generate
    for (g = 0; g < 3; g = g + 1) begin : g_corner
      p2_fp_in_single u_x (.u(pr.x[g]), .ranged(1'b1), .o_neg(xf[g].neg), .o_bad(xf[g].bad), .o_exp(xf[g].exp), .o_mant(xf[g].mant));
      p2_fp_in_single u_y (.u(pr.y[g]), .ranged(1'b1), .o_neg(yf[g].neg), .o_bad(yf[g].bad), .o_exp(yf[g].exp), .o_mant(yf[g].mant));
      p2_fp_in_single u_z (.u(pr.z[g]), .ranged(1'b1), .o_neg(zf[g].neg), .o_bad(zf[g].bad), .o_exp(zf[g].exp), .o_mant(zf[g].mant));
      p2_fp_in_single u_u (.u(pr.u[g]), .ranged(1'b1), .o_neg(uf[g].neg), .o_bad(uf[g].bad), .o_exp(uf[g].exp), .o_mant(uf[g].mant));
      p2_fp_in_single u_v (.u(pr.v[g]), .ranged(1'b1), .o_neg(vf[g].neg), .o_bad(vf[g].bad), .o_exp(vf[g].exp), .o_mant(vf[g].mant));
      for (h = 0; h < 4; h = h + 1) begin : g_ch
        logic [31:0] cw, ow;
        p2_fp_in_colour u_cc (.c(cc[g][h]), .w(cw));
        p2_fp_in_colour u_oc (.c(oc[g][h]), .w(ow));
        p2_fp_in_single u_cs (.u(cw), .ranged(1'b1), .o_neg(cf[g][h].neg), .o_bad(cf[g][h].bad), .o_exp(cf[g][h].exp),
          .o_mant(cf[g][h].mant));
        p2_fp_in_single u_os (.u(ow), .ranged(1'b1), .o_neg(of[g][h].neg), .o_bad(of[g][h].bad), .o_exp(of[g][h].exp),
          .o_mant(of[g][h].mant));
      end
    end
  endgenerate
  always_comb begin
    p2_fp24_t third, k2;
    third      = '0;
    third.mant = 24'hAAAAAB;                    // pvrfp::OneThird(): the single nearest 1/3, a hair above
    third.exp  = -10'sd25;
    k2         = '0;
    k2.mant    = 24'h95F612;                    // MipSelect's length: 0x3F15F612, a little under 2 - sqrt(2)
    k2.exp     = -10'sd24;
    ld_val = '0;
    ld_val[P2_TSP_R_X0] = xf[0];  ld_val[P2_TSP_R_X1] = xf[1];  ld_val[P2_TSP_R_X2] = xf[2];
    ld_val[P2_TSP_R_Y0] = yf[0];  ld_val[P2_TSP_R_Y1] = yf[1];  ld_val[P2_TSP_R_Y2] = yf[2];
    ld_val[P2_TSP_R_Z0] = zf[0];  ld_val[P2_TSP_R_Z1] = zf[1];  ld_val[P2_TSP_R_Z2] = zf[2];
    ld_val[P2_TSP_R_THIRD] = third;
    ld_val[P2_TSP_R_K2]    = k2;
    ld_val[P2_TSP_R_ATU0] = uf[0];  ld_val[P2_TSP_R_ATU1] = uf[1];  ld_val[P2_TSP_R_ATU2] = uf[2];
    ld_val[P2_TSP_R_ATV0] = vf[0];  ld_val[P2_TSP_R_ATV1] = vf[1];  ld_val[P2_TSP_R_ATV2] = vf[2];
    ld_val[P2_TSP_R_ATCB0] = cf[0][0];  ld_val[P2_TSP_R_ATCB1] = cf[1][0];  ld_val[P2_TSP_R_ATCB2] = cf[2][0];
    ld_val[P2_TSP_R_ATCG0] = cf[0][1];  ld_val[P2_TSP_R_ATCG1] = cf[1][1];  ld_val[P2_TSP_R_ATCG2] = cf[2][1];
    ld_val[P2_TSP_R_ATCR0] = cf[0][2];  ld_val[P2_TSP_R_ATCR1] = cf[1][2];  ld_val[P2_TSP_R_ATCR2] = cf[2][2];
    ld_val[P2_TSP_R_ATCA0] = cf[0][3];  ld_val[P2_TSP_R_ATCA1] = cf[1][3];  ld_val[P2_TSP_R_ATCA2] = cf[2][3];
    ld_val[P2_TSP_R_ATOB0] = of[0][0];  ld_val[P2_TSP_R_ATOB1] = of[1][0];  ld_val[P2_TSP_R_ATOB2] = of[2][0];
    ld_val[P2_TSP_R_ATOG0] = of[0][1];  ld_val[P2_TSP_R_ATOG1] = of[1][1];  ld_val[P2_TSP_R_ATOG2] = of[2][1];
    ld_val[P2_TSP_R_ATOR0] = of[0][2];  ld_val[P2_TSP_R_ATOR1] = of[1][2];  ld_val[P2_TSP_R_ATOR2] = of[2][2];
    ld_val[P2_TSP_R_ATOA0] = of[0][3];  ld_val[P2_TSP_R_ATOA1] = of[1][3];  ld_val[P2_TSP_R_ATOA2] = of[2][3];
  end

  // the job's state
  logic [1:0][31:0] zbits;
  always_ff @(posedge clk) begin
    if (rst) begin
      act <= 1'b0;
      pc  <= '0;
    end else begin
      if (take) begin
        act   <= 1'b1;
        pc    <= '0;
        cls   <= cls_in;
        len   <= p2_tsp_len(cls_in);
        sidx  <= pr.job.sidx;
        j_mipd <= pr.tsp[11:8];
        j_texu <= pr.tsp[5:3];
        zbits <= {pr.z[1], pr.z[0]};
      end else if (last) begin
        act <= 1'b0;
      end else if (step) begin
        pc <= pc + P2_TSP_PC_BITS'(1);
      end
    end
  end

  // ---------------------------------------------------------------------------------------------- the ALU
  p2_fp24_t [P2_TSP_NREG-1:0] rf;
  p2_tsp_alu u_alu (
    .clk, .rst, .issue(step), .uw, .ld(take), .ld_val, .zbits, .rf, .t_wv, .t_wrd);

  // ---------------------------------------------------------------------------------------------- the store writes
  p2_fp24_t sdet, wa, wb, wc, wf;
  logic     mean_neg, perp, flat, dz;
  assign sdet     = rf[P2_TSP_R_SDET];
  assign mean_neg = rf[P2_TSP_R_MEAN].neg;
  assign wa   = rf[uw.w.r[0]];
  assign wb   = rf[uw.w.r[1]];
  assign wc   = rf[uw.w.r[2]];
  assign wf   = rf[uw.w.r[3]];
  p2_fp_perp u_perp (.det_bad(sdet.bad), .det_exp(sdet.exp), .det_mant(sdet.mant), .fpu_perp_val(fpu_perp_val), .perp(perp));
  assign dz   = sdet.mant == '0 && !sdet.bad;
  assign flat = dz || perp;

  p2_fp16_t ca, cb, cc16, cf16;
  p2_fp_cut #(.IW(24), .N(16)) u_ca (.i_neg(wa.neg), .i_bad(wa.bad), .i_exp(wa.exp), .i_mant(wa.mant),
    .o_neg(ca.neg), .o_bad(ca.bad), .o_exp(ca.exp), .o_mant(ca.mant));
  p2_fp_cut #(.IW(24), .N(16)) u_cb (.i_neg(wb.neg), .i_bad(wb.bad), .i_exp(wb.exp), .i_mant(wb.mant),
    .o_neg(cb.neg), .o_bad(cb.bad), .o_exp(cb.exp), .o_mant(cb.mant));
  p2_fp_cut #(.IW(24), .N(16)) u_cc (.i_neg(wc.neg), .i_bad(wc.bad), .i_exp(wc.exp), .i_mant(wc.mant),
    .o_neg(cc16.neg), .o_bad(cc16.bad), .o_exp(cc16.exp), .o_mant(cc16.mant));
  p2_fp_cut #(.IW(24), .N(16)) u_cf (.i_neg(wf.neg), .i_bad(wf.bad), .i_exp(wf.exp), .i_mant(wf.mant),
    .o_neg(cf16.neg), .o_bad(cf16.bad), .o_exp(cf16.exp), .o_mant(cf16.mant));

  // K: best (the w slot's r[0], wa) times the bias, the size added to its exponent, cut to 8 bits
  logic [3:0]   bias;
  logic [3:0]   size;           // 3 + TexU: 3 .. 10
  p2_fp24_t     best;
  logic [28:0]  kp;             // best x 2 bias, exact (24 x 5 bits): FromHalves(2 bias) is {mant 2 bias, exp -1}
  logic [7:0]   k8m;
  assign bias = (j_mipd == 4'd0) ? 4'd4 : j_mipd;
  assign size = 4'd3 + {1'b0, j_texu};
  always_comb begin
    best = wa;
    if (dz) begin
      best      = '0;
      best.mant = 24'hFFFFFF;
      best.exp  = -10'sd23;
    end
  end
  // Mul(best, FromHalves(2 bias), 62), exact: mant best.mant x 2 bias at best.exp - 1; exp += size - 2; then cut(8) (the
  // tuple as refsw3 has it: a product of at most 8 bits is not normalized)
  assign kp = {5'h00, best.mant} * {24'h0, bias, 1'b0};
  logic signed [P2_FP_EW-1:0] kpe, k8e;
  assign kpe = best.exp + $signed({{(P2_FP_EW - 4){1'b0}}, size}) - P2_FP_EW'(3);
  p2_fp_cut #(.IW(29), .N(8)) u_k8 (.i_neg(1'b0), .i_bad(1'b0), .i_exp(kpe), .i_mant(kp),
    .o_neg(), .o_bad(), .o_exp(k8e), .o_mant(k8m));

  always_comb begin
    sh_v   = take;
    sh_idx = pr.job.sidx;
    sh_w   = hdr;
    sp_v     = step && uw.w.v && (uw.w.op == P2_TSP_W_PL || uw.w.op == P2_TSP_W_DR);
    sp_idx   = sidx;
    sp_plane = uw.w.plane;
    sp_w     = '0;
    if (uw.w.op == P2_TSP_W_PL) begin
      if (flat) begin
        sp_w.a = '0;
        sp_w.b = '0;
        sp_w.c = cf16;
      end else begin
        sp_w.a = ca;
        sp_w.b = cb;
        sp_w.c = cc16;
      end
    end else begin
      // a dropped offset plane (ARCHITECTURE 3.7.3's table)
      sp_w.a = '0;
      sp_w.b = '0;
      sp_w.c = '0;
      if (flat) begin
        sp_w.c.neg = mean_neg;
      end else begin
        sp_w.a.neg = sdet.neg;
        sp_w.b.neg = sdet.neg;
        sp_w.c.neg = sdet.neg;
      end
    end
    sk_v   = step && uw.w.v && uw.w.op == P2_TSP_W_K;
    sk_idx = sidx;
    sk_w   = '0;
    sk_w.dz = dz;
    if (best.bad) begin
      sk_w.k8.mant = 8'd1;
      sk_w.k8.exp  = P2_FP_EW'(-128) + $signed({{(P2_FP_EW - 4){1'b0}}, size});
    end else if (best.mant == '0) begin
      sk_w.k8.mant = 8'd1;
      sk_w.k8.exp  = P2_FP_EW'(-127) + $signed({{(P2_FP_EW - 4){1'b0}}, size});
    end else begin
      sk_w.k8.mant = k8m;
      sk_w.k8.exp  = k8e;
    end
    done     = last;
    done_idx = sidx;
  end

  assign t_issue = step;
  assign t_cls   = cls;
  assign t_pc    = pc;
  assign t_uw    = uw;
endmodule
